(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["pt-br"] = {"ui":{"skip":"Ir para o conteúdo","back":"← Voltar para o AI-gile","lang.button":"Idioma: {name}","lang.dialog":"Escolha um idioma","lang.search":"Buscar idiomas","lang.none":"Nenhum idioma encontrado","lang.notYet":"{name} ainda não foi traduzido","theme.aria":"Alternar entre tema claro e escuro","theme.toLight":"Mudar para o tema claro","theme.toDark":"Mudar para o tema escuro","words.underline":"Sublinhar essas palavras na página","words.underlineHelp":"Passe o mouse ou toque numa palavra pontilhada para ver o que ela significa.","index.title":"AI-gile: seu time de dev com IA, em um só quadro","index.description":"O AI-gile é um quadro kanban para times de código com IA. Eles trabalham enquanto você dorme; você recebe uma pilha curta de coisas para decidir, testar e aceitar.","hero.logoAlt":"Ícone do quadro AI-gile","hero.h1.html":"Seu time de dev com IA, em um só&nbsp;quadro.","hero.alpha":"🐣 Pré-alfa fechado","hero.alphaTitle":"Cedo e inacabado: obrigado por experimentar!","hero.lede":"Eles constroem enquanto você dorme. Você acorda com uma pilha curta: algumas perguntas, algumas coisas para testar, um ou dois diamantes roxos. Clique, aceite, volte para o seu café.","dl.windows":"App para Windows","dl.browser":"Use no navegador","dl.soon":"Em breve","dl.notify":"🔔 Avise-me quando abrir","dl.notifySmall":"Alfa ou beta","hero.secondary":"Ágil, mas o time nunca precisa de café em pé para a daily. (Mesmo assim eles fazem a daily.)","pitch.h2":"O AI-gile em quantas palavras você quiser","pitch.lede":"Escolha um tamanho, de uma palavra a 144. Cada tamanho é uma descrição própria, escrita para ele. Arraste o controle ou use as setas do teclado.","pitch.rangeLabel":"Tamanho em palavras","pitch.dice":"🎲 outra versão","pitch.words.one":"{n} palavra","pitch.words.other":"{n} palavras","pitch.letters.one":"{n} letra","pitch.letters.other":"{n} letras","pitch.chars.one":"{n} caractere","pitch.chars.other":"{n} caracteres","count.line.html.one":"{n} card no quadro agora","count.line.html.other":"{n} cards no quadro agora","features.aria":"O que ele faz","f.pile.h":"Uma pilha só para você","f.pile.html":"<b>Para você</b> reúne tudo o que está esperando por você, em todos os projetos: perguntas, coisas para testar, tarefas que só um humano pode fazer. Sua fila diz o que vem a seguir e quanto tempo leva.","f.sleep.h":"Times que trabalham enquanto você dorme","f.sleep.p":"Cada projeto tem um líder e um time de agentes de IA. Comente em um card e o time acorda, faz o trabalho e devolve com passos que um humano cansado consegue seguir.","f.tester.h":"Um testador de IA confere primeiro","f.tester.p":"Antes de qualquer coisa chegar a você, um testador segue os passos em uma cópia do app e mostra o que viu, com uma captura de tela. Passe os aprovados e aceite com um clique.","f.proof.h":"Provas, não promessas","f.proof.p":"Toda entrega mostra o que mudou: os arquivos, o diff, as capturas de tela. Sem abrir cada app para ver se já ficou pronto.","f.chat.h":"Converse com seus líderes","f.chat.p":"Uma barra no estilo Discord: um ícone por projeto, diamantes roxos para o que precisa de você. Mande uma ideia a um líder; ele a transforma em cards e um plano, com um botão ✅ Go.","f.tidy.h":"Se mantém organizado","f.tidy.p":"Cards parecidos se juntam em um, títulos confusos são corrigidos e uma checagem de tokens mantém o código enxuto. Menos coisas para alternar, menos para pensar.","f.private.h":"Seu, no seu computador","f.private.li1":"O quadro roda na sua própria máquina e só responde a você.","f.private.li2":"As DMs privadas entre pessoas têm criptografia de ponta a ponta.","f.private.li3":"Sem contas, sem rastreadores, sem cookies.","f.lang.h":"No seu idioma","f.lang.p":"Mais de 120 idiomas, do holandês, galês e japonês ao pirata, Yoda e klingon, com uma troca rápida para o inglês nas palavras de desenvolvedor.","tl.aria":"Linha do tempo da primeira conversa até o roteiro","tl.h2":"Do primeiro papo ao que vem por aí","tl.lede":"Datas e horas reais, no seu fuso horário. Depois de hoje é o plano, sem datas prometidas.","tl.today":"Hoje","tl.planned":"planejado","tl.cards.one":"{n} card","tl.cards.other":"{n} cards","join.h2":"Participe","join.lede":"O AI-gile está sendo construído por um humano pequeno e um monte de agentes pacientes. Por enquanto é privado, em um alfa fechado com amigos. Quer experimentar quando abrir?","join.btn":"Registrar interesse","join.small":"Vamos escrever por e-mail, mais nada","footer.tag":"AI-gile. Sem rastreadores, sem cookies, sem café em pé.","footer.licence":"Licença comercial","footer.status":"Status","footer.privacy":"O que guardamos","form.sending":"Enviando…","form.failed":"Não deu certo: tente de novo mais tarde.","form.offline":"Não consegui falar com o AI-gile: tente de novo mais tarde.","form.keep":"Só usamos isso para responder a você e depois apagamos. Sem rastreadores, sem cookies.","form.keepLink":"O que guardamos","interest.title":"AI-gile: avise-me quando o alfa abrir","interest.description":"Deixe seu e-mail para saber quando o alfa ou beta fechado do AI-gile abrir.","interest.h1":"🔔 Avise-me quando abrir","interest.lede":"O AI-gile está em pré-alfa fechado. Deixe seu e-mail e escreveremos uma vez, quando houver um lugar para você.","interest.email":"Seu e-mail","interest.which":"Qual teste?","interest.alpha":"Alfa fechado: cedo, cru, com muitas mudanças","interest.beta":"Beta: mais firme, mais tarde","interest.both":"Tanto faz, o que vier primeiro","interest.submit":"Coloque-me na lista","interest.thanks":"Obrigado! Você está na lista.","licence.title":"AI-gile: licença comercial","licence.description":"Vai usar o AI-gile na sua empresa? Peça uma licença comercial gratuita.","licence.h1":"📜 Licença comercial","licence.lede":"Vai usar o AI-gile no trabalho? Conte quem você é e o que faz. Se faz algum bem, a licença é gratuita.","licence.company":"Empresa","licence.website":"Site","licence.what":"O que você faz","licence.how":"Como isso ajuda o mundo","licence.email":"E-mail","licence.submit":"Solicitar","licence.thanks":"Obrigado! Responderemos por e-mail.","status.title":"Status do AI-gile","status.h1":"Status do AI-gile","status.quiet":"Tudo calmo","status.intro":"O AI-gile está funcionando agora? Esta página verifica o site, o compartilhamento de quadros, as chamadas e o download a cada 5 minutos.","status.up":"Funcionando (respondeu em {ms} ms)","status.slow":"Não respondeu à última verificação, tentando de novo","status.down":"Fora do ar: não respondeu às duas últimas verificações","status.svc.web":"Site","status.svc.web.offers":"Este site: o que é o AI-gile e o formulário de interesse","status.svc.boards":"Compartilhamento de quadros","status.svc.boards.offers":"Quadros públicos, mensagens entre amigos e convites","status.svc.calls":"Chamadas","status.svc.calls.offers":"Voz, vídeo e compartilhamento de tela no AI-gile","status.svc.download":"Download","status.svc.download.offers":"O instalador para Windows e os links de convite","status.checking":"Verificando…","status.offline":"Não consigo falar com o serviço de status agora (tentando de novo)","status.updated":"atualizado {ago}","status.justNow":"agora mesmo","status.min":"há {n} min","status.hours":"há {n} h","status.days":"há {n} d","privacy.title":"AI-gile: o que guardamos","privacy.h1":"O que guardamos","privacy.lede":"Resumindo: só o que você nos envia, e não por muito tempo.","privacy.only":"Só o que você nos envia: o que você digita num formulário, como seu e-mail. Nada mais sobre você.","privacy.sealed":"É lacrado para que nosso servidor não consiga ler: no seu navegador, antes de sair (num navegador mais antigo, no momento em que chega). Só o nosso próprio quadro consegue abrir.","privacy.server":"É apagado do servidor assim que chega ao nosso quadro. O que ainda estiver lá depois de 30 dias é apagado de qualquer jeito.","privacy.board":"Guardamos no nosso quadro só até responder a você, e depois apagamos de lá também.","privacy.none":"Sem rastreadores, sem cookies, sem análises.","privacy.local":"Seu idioma e a escolha entre tema claro ou escuro ficam no seu próprio navegador. Nunca são enviados para nós.","privacy.ask":"Quer que seja apagado antes? Responda ao nosso e-mail e avise.","live.h2":"Veja sendo construído, ao vivo","live.caption":"Cada cartão está escondido: você vê o formato do trabalho, não as palavras.","live.watching.one":"ao vivo: {n} assistindo","live.watching.other":"ao vivo: {n} assistindo","live.last.now":"Último cartão movido agora há pouco","live.last.min.one":"Último cartão movido há {n} min","live.last.min.other":"Último cartão movido há {n} min","live.last.hour.one":"Último cartão movido há {n} hora","live.last.hour.other":"Último cartão movido há {n} horas","live.last.day.one":"Último cartão movido há {n} dia","live.last.day.other":"Último cartão movido há {n} dias","live.offline":"O quadro ao vivo está tomando um fôlego. Volte logo.","live.cols":"Backlog|A fazer|Em andamento|A equipe verifica|Para você testar|Para a equipe|Concluído"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robôs.","Delegado."]},{"n":2,"texts":["Kanban robótico.","Agentes, organizados.","Ideias, construídas."]},{"n":3,"texts":["Kanban para robôs.","Ideias viram funcionalidades.","Kanban de agentes, grátis."]},{"n":5,"texts":["Quadro kanban tocado por agentes.","Você escreve cards. Agentes constroem.","Grátis, local, testado, um pouco bobo."]},{"n":8,"texts":["Um kanban grátis onde agentes de IA trabalham.","Escreva uma ideia. Agentes constroem. Você aceita.","Ágil para um humano e muitos robôs pacientes."]},{"n":13,"texts":["Um quadro kanban no seu computador, onde agentes de IA pegam os cards.","Escreva uma ideia. Um time de agentes constrói. Um testador confere.","Grátis, sem contas, sem rastreadores: um quadro, uns robôs e você no comando."]},{"n":21,"texts":["O AI-gile é um quadro kanban para trabalhar com agentes de código de IA. Eles pegam os cards; você testa e aceita.","Cada projeto ganha um líder e um time de agentes de IA. Comente em qualquer card e o time põe a mão na massa.","Um quadro pessoal e gratuito que roda no seu próprio computador. Quem trabalha são robôs. Quem diz sim é você."]},{"n":34,"texts":["Você põe ideias em um quadro. Um time de agentes de IA as transforma em funcionalidades que funcionam, testa tudo e devolve com passos para experimentar. Nada vale como pronto até você dizer que sim.","O AI-gile é um quadro kanban caseiro que o Rich construiu com muita ajuda dos agentes que ele agora gerencia. É gratuito, roda no seu computador e é compartilhado com amigos, não vendido.","Imagine um quadro kanban comum, com colunas do Backlog até Concluído, só que os cards são pegos por agentes de IA. Eles contam o andamento, perguntam quando travam e sempre esperam o seu joinha."]},{"n":55,"texts":["O AI-gile é um quadro kanban em que o time é feito de agentes de IA. Cada projeto tem um líder que planeja o trabalho e ajudantes que o constroem. Quando uma funcionalidade fica pronta, um testador de IA a experimenta e tira uma captura de tela, e então ela cai na sua pilha. Aceite, ou comente e eles refazem.","Começou como o jeito de uma pessoa acompanhar várias sessões de código com IA ao mesmo tempo e virou um quadro de verdade. Roda na sua máquina, não pede conta e não tem rastreadores. É grátis para amigos e curiosos. Também está inacabado, então espere arestas e uma surpresa de vez em quando.","Vamos ser sinceros. Você ainda precisa ter as ideias e ainda precisa conferir os resultados. O que o AI-gile faz é tudo o que fica no meio: mantém os cards em ordem, acorda o agente certo quando você comenta, mostra exatamente o que mudou e reúne tudo em uma pilha curta para você."]},{"n":89,"texts":["O AI-gile é um quadro kanban gratuito que você roda no seu próprio computador. Em vez de pessoas, cada projeto tem um time de agentes de IA: um líder que transforma suas ideias em cards e um plano, e ajudantes que pegam os cards por ordem de prioridade. Quando algo fica pronto, um testador de IA segue os passos de teste e mostra o que viu. Depois tudo espera em uma pilha chamada Para você. Você aceita, ou comenta e o time tenta de novo. Nada chega a Concluído sem você.","Alguns recursos que você talvez não espere. Um vigia da noite mantém a coluna A fazer abastecida enquanto você dorme, escolhendo cards que não precisam de resposta sua. Um contador de tokens mostra quanto os agentes gastaram hoje e nesta semana, e o Modo Sem Tokens manda todos pararem de gastar. Você pode conversar com amigos, e as mensagens privadas têm criptografia de ponta a ponta. O quadro fala cerca de 120 idiomas, entre eles holandês, flamengo, pirata e klingon. Nada disso custa um centavo, e ninguém quer vender nada a você.","O AI-gile é um projeto pequeno e pessoal, não uma empresa. O Rich queria cuidar de vários projetos de código com IA sem abrir cada app para dar uma olhada, então ele e os agentes construíram um quadro para isso e depois usaram o quadro para construir o resto dele mesmo. Está em pré-alfa fechado, ou seja, funciona, quase sempre, para um punhado de amigos. Não há página de preços, newsletter nem plano de crescimento. Se parece útil, peça para experimentar quando abrir um pouco mais."]},{"n":144,"texts":["O AI-gile é um quadro kanban para um humano e muitos agentes de IA. Roda no seu próprio computador e é totalmente gratuito. Você adiciona projetos, e cada projeto ganha um líder e um time pequeno. Você conversa com o líder, mais ou menos como no Discord, e descreve uma ideia; o líder a transforma em cards e um plano, e espera você apertar Go. O time vai passando pelos cards por ordem de prioridade, usando uma linha de comando simples feita para modelos de linguagem. Antes de qualquer coisa voltar para você, um testador de IA segue os passos em uma cópia do app e anexa uma captura de tela. O trabalho pronto cai na sua pilha com os arquivos alterados e o diff. Você aceita, ou deixa um comentário e o time acorda e tenta de novo. Só você pode mover um card para Concluído.","Um dia com o AI-gile, mais ou menos. À noite você deixa alguns comentários: este botão está no lugar errado, aquela lista deveria ser ordenada, dava para ter um modo escuro. Você vai dormir. Os agentes leem os comentários, fazem as mudanças, testam e devolvem para você. Se o A fazer esvazia, o vigia da noite o reabastece com cards do backlog que não precisam de resposta sua. De manhã há uma pilha curta: algumas perguntas e algumas coisas para experimentar, cada uma com passos que uma pessoa sonolenta consegue seguir e uma captura de tela dela funcionando. Você passa por tudo, aceita o que está bom e devolve o resto. Um contador de tokens mostra o que tudo isso gastou, e o Modo Sem Tokens existe para as semanas magras. Depois você toma o café da manhã, e nisso os agentes ainda não ajudam.","Primeiro, o que o AI-gile não é. Não é uma startup, não está à venda e ninguém coleta seus dados. É um quadro gratuito que roda no seu computador, sem contas, sem rastreadores e sem cookies. O que ele é: um lugar organizado para ver todos os seus projetos de código com IA de uma vez, com um time de agentes cuidando dos cards e você tomando as decisões. Ele junta cards parecidos, corrige títulos confusos e fica de olho em quão enxuto o código se mantém. Fala cerca de 120 idiomas, do holandês e do flamengo ao pirata e ao klingon. Amigos podem trocar mensagens, em privado e com criptografia. Foi construído pelo Rich e por um monte de agentes pacientes, usando a si mesmo na maior parte do tempo. Está em pré-alfa fechado, então ainda é cru em alguns pontos. Se parece divertido, peça com jeitinho e talvez você entre mais cedo."]}],"quips":{"1":"Uma palavra. Ousado. Talvez ousado demais.","3":"Três palavras. Já mais honesto que a maioria das páginas de produto.","8":"Oito palavras. Ainda mais curto que uma daily.","21":"Os tamanhos são story points, aliás. Claro que são.","55":"Cinquenta e cinco palavras. Dois cards ficaram prontos enquanto você lia.","144":"Esse é o longo. Não existe 233. Os agentes foram dormir."}},"timeline":{"first-idea.name":"A primeira ideia","first-idea.line":"A primeiríssima conversa, antes de existir qualquer código.","first-board.name":"Primeiro quadro","first-board.line":"Um quadro que acompanha a própria construção: cards, colunas, arrastar e soltar, projetos.","team-roles.name":"Time e funções","team-roles.line":"Perfis de agentes, modelos de time, espaços e quem faz o quê.","install.name":"Instalação e versões","install.line":"Um zip que um amigo instala, com atualização automática, canais e volta atrás.","usage-saver.name":"Economia de uso","usage-saver.line":"Medir o custo de cada execução, manter o código enxuto, poupar seu limite.","friends.name":"Amigos e compartilhamento","friends.line":"DMs privadas, um relay embaralhado, convites, funções e projetos compartilhados.","languages.name":"Idiomas","languages.line":"Todo texto de tela em um arquivo de idioma, começando pelo holandês e o flamengo.","ai-tester.name":"Testador de IA","ai-tester.line":"Um testador confere cada entrega primeiro e mostra o que viu.","website.name":"O site","website.line":"aigile.lol, a página de apresentação e esta linha do tempo.","streaming.name":"Chat e transmissão","streaming.line":"Discord, Twitch, OBS, modo streamer, GIFs e emojis.","no-ai.name":"Edição sem IA","no-ai.line":"Um quadro para quem programa sem IA, e quadros públicos.","night-watch.name":"Vigia da noite","night-watch.line":"Um vigia e Scrum Master mantêm os times no rumo enquanto você dorme.","p-more.name":"Todo o resto","p-more.line":"Ideias menores ainda esperando a vez.","p-android.name":"Celular e Android","p-android.line":"Acesse seu quadro pelo celular e, depois, um app Android nativo.","p-release.name":"Alfa e além","p-release.line":"Alfa fechado, o site no ar e depois o beta.","p-languages.name":"Mais idiomas","p-languages.line":"Mais de cem idiomas e um modo de imersão para quem está aprendendo.","p-engines.name":"Mais motores de IA","p-engines.line":"Escolha Claude, Codex ou Gemini para cada agente.","p-pro.name":"Prática profissional","p-pro.line":"Rótulos de risco, portões de merge, cards de incidente e proteções.","p-self.name":"Cuidando de você","p-self.line":"Modo cansado, lembretes de autocuidado e 4:20.","p-servers.name":"Servidores e escala","p-servers.line":"Configurações globais de servidor, funções e planejamento para crescer.","p-livestream.name":"Extras de transmissão","p-livestream.line":"Chat da Twitch, emojis personalizados e uma visão pública ao vivo."},"words":{"button":"📖 Termos de programação","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Buscar uma palavra…","none":"Nenhuma palavra corresponde.","close":"Fechar","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"A pasta de código do projeto e todo o seu histórico de commits, normalmente também salva no GitHub.","also":["repositório","repository"]},{"id":"branch","g":"build","word":"Branch","text":"Uma linha de trabalho separada no código, para fazer alterações sem tocar na versão principal.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Um instantâneo salvo do código, com uma nota curta do que mudou. Você sempre pode voltar a um deles.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Enviar os instantâneos salvos (commits) deste computador para o GitHub, para ficarem com backup e compartilhados."},{"id":"merge","g":"build","word":"Merge","text":"Integrar as alterações de um branch na versão principal."},{"id":"pr","g":"build","word":"Pull request","text":"Pedir que as alterações de um branch sejam verificadas e integradas na versão principal.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Arrumar o código sem mudar o que ele faz: arquivos menores, nomes mais claros, menos repetição."},{"id":"bug","g":"build","word":"Bug","text":"Algo que não funciona como deveria.","also":["bugs"]},{"id":"test","g":"build","word":"Teste","text":"Experimentar um trabalho terminado para verificar se faz o que foi pedido, antes de aceitá-lo.","also":["testes","testar"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Colocar uma nova versão no ar, por exemplo em um servidor onde as pessoas a usam."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Ideias e trabalho que ainda não foram planejados. Nada ali é trabalhado até passar para A fazer."},{"id":"sprint","g":"team","word":"Sprint","text":"Um período curto de trabalho (muitas vezes uma ou duas semanas) com um conjunto combinado de cards para concluir.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Uma checagem rápida: o que cada membro da equipe fez, o que vai fazer em seguida e o que está travando o trabalho.","also":["standup","stand-ups","daily"]},{"id":"kanban","g":"team","word":"Kanban","text":"Um quadro com colunas (A fazer, Em andamento, Concluído) onde os cards vão da esquerda para a direita conforme o trabalho avança."},{"id":"wip","g":"team","word":"Limite de WIP","text":"Work in progress (trabalho em andamento): o máximo de cards que uma coluna deve ter, para a equipe terminar as coisas antes de começar mais.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agente","text":"Uma IA que trabalha sozinha em uma tarefa: lê o código, faz alterações, roda verificações e informa o resultado.","also":["agentes","agent"]},{"id":"token","g":"team","word":"Token","text":"A unidade em que o uso da IA é contado: aproximadamente algumas letras de texto lidas ou escritas. Menos tokens, mais sobra do seu plano.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Um pequeno comando que roda sozinho em um momento definido, por exemplo quando uma sessão de IA começa, para a equipe ouvir seus comentários.","also":["hooks"]}]}};
